steps.command:
\
SUBJECT=$(openssl x509 -in server.crt -noout -subject) && \
DATES=$(openssl x509 -in server.crt -noout -dates) && \
FPR=$(openssl x509 -in server.crt -noout -fingerprint -sha256) && \
{
  echo "Certificate: server.crt";
  echo "Subject: $SUBJECT";
  echo "$DATES";
  echo "SHA-256 Fingerprint: $FPR";
  echo "";
  echo "--- Parsed ---";
  echo "Subject: $(openssl x509 -in server.crt -noout -subject -nameopt RFC2253)";
  echo "Not Before (YYYY-MM-DD): $(openssl x509 -in server.crt -noout -startdate | cut -d= -f2 | xargs -I{} date -u -d {} +%Y-%m-%d)";
  echo "Not After (YYYY-MM-DD): $(openssl x509 -in server.crt -noout -enddate | cut -d= -f2 | xargs -I{} date -u -d {} +%Y-%m-%d)";
  echo "SHA-256 Fingerprint: $(openssl x509 -in server.crt -noout -fingerprint -sha256 | cut -d= -f2)";
} > verification.txt && cat verification.txt
